The restricted runtime disallows `fractions`, so I’m rerunning the exact state propagation with integer-scaled floating-point probabilities. The transition model will explicitly handle an exhausted ramp and stop when no balls remain.
I’m applying the stated rules directly, with empty ramp slots represented by zero and empty-platform states retained until all balls have exited. This avoids the earlier malformed shell quoting and the unavailable import.
```python
states = {(1, 2, 3, 4): 1.0}
ejected = {}
rounds = 0

while states:
    next_states = {}
    for (a, b, c, k), mass in states.items():
        if a == 0 and b == 0 and c == 0:
            continue

        for piston in (1, 2, 3):
            share = mass / 3.0

            if piston == 1:
                if a != 0:
                    ejected[a] = ejected.get(a, 0.0) + share
                na = b
                nb = c
                nc = k if k <= 100 else 0
                nk = k + 1

            elif piston == 2:
                if b != 0:
                    ejected[b] = ejected.get(b, 0.0) + share
                na = c
                nb = k if k <= 100 else 0
                nc = k + 1 if k + 1 <= 100 else 0
                nk = k + 2

            else:
                if c != 0:
                    ejected[c] = ejected.get(c, 0.0) + share
                na = b
                nb = k if k <= 100 else 0
                nc = k + 1 if k + 1 <= 100 else 0
                nk = k + 2

            state = (na, nb, nc, nk)
            next_states[state] = next_states.get(state, 0.0) + share

    states = next_states
    rounds += 1

best_probability = max(ejected.values())
best_balls = [ball for ball in ejected if abs(ejected[ball] - best_probability) < 1e-12]

print(f"best_balls={best_balls}, probability={best_probability}, rounds={rounds}")
```

